function readMedia(raw={}){const records={};if(raw===null||typeof raw!=='object'||Array.isArray(raw))throw Error('配置媒体格式无效');for(const key of ['background','cursor','beatSound']){const item=raw[key];if(item===undefined)continue;if(!item||typeof item!=='object'||typeof item.mime!=='string'||!/^(image|video|audio)\/[a-z0-9.+-]+$/i.test(item.mime)||key==='cursor'&&!item.mime.startsWith('image/')||key==='beatSound'&&!item.mime.startsWith('audio/')||key==='background'&&!/^(image|video)\//.test(item.mime)||typeof item.base64!=='string')throw Error('配置媒体类型无效');const base64=item.base64.replace(/\s+/g,'');if(!base64||!/^(?:[a-z0-9+/]{4})*(?:[a-z0-9+/]{2}==|[a-z0-9+/]{3}=)?$/i.test(base64))throw Error('配置媒体 base64 无效');records[key]={name:String(item.name||key).slice(0,200),mime:item.mime,data:Uint8Array.from(atob(base64),x=>x.charCodeAt(0))};}return records;}
