async function loadImage(record,label){if(!record?.data?.length)throw Error(label+'为空');const url=URL.createObjectURL(new Blob([record.data],{type:record.mime}));try{const image=await new Promise((resolve,reject)=>{const img=new Image(),timer=setTimeout(()=>finish(Error(label+'读取超时，请重新导入')),6000);let done=false;function finish(error){if(done)return;done=true;clearTimeout(timer);img.onload=img.onerror=null;if(error){try{img.src='';}catch(e){}reject(error);}else resolve(img);}img.onload=()=>finish((img.naturalWidth||img.width)>0&&(img.naturalHeight||img.height)>0?null:Error(label+'尺寸无效'));img.onerror=()=>finish(Error(label+'无法解码为图片'));try{img.src=url;}catch(err){finish(err);}});return{image,url};}catch(err){URL.revokeObjectURL(url);throw err;}}
async function prepareCursor(record){const stage=await loadImage(record,'光标图片');stage.record=record;stage.pixels=null;stage.supports=new Map();try{const cv=document.createElement('canvas'),scale=Math.min(1,256/Math.max(stage.image.naturalWidth,stage.image.naturalHeight));cv.width=Math.max(1,Math.round(stage.image.naturalWidth*scale));cv.height=Math.max(1,Math.round(stage.image.naturalHeight*scale));const cx=cv.getContext('2d');cx.drawImage(stage.image,0,0,cv.width,cv.height);const rgba=cx.getImageData(0,0,cv.width,cv.height).data;stage.pixels=[];for(let y=0;y<cv.height;y++)for(let x=0;x<cv.width;x++)if(rgba[(y*cv.width+x)*4+3]>=64)stage.pixels.push([(x+.5)/cv.width-.5,(y+.5)/cv.height-.5]);}catch(err){}return stage;}
function currentCursor(){return{record:cursorRecord,image:cursorImage,pixels:cursorPixels,supports:cursorSupports,url:cursorURL};}
