const fieldNames={bg:'页面底色',panel:'面板',panel2:'次级面板',border:'边框',text:'正文',muted:'次级文字',accent:'强调色',accent2:'次强调色','on-accent':'强调色文字',grid:'编辑底色',laneA:'轨道奇数',laneB:'轨道偶数',gridline:'网格',strongline:'强网格',danger:'危险操作',note:'音符备用色'};
const fields={style:[['theme','主题','select',[['day','白黑 · 日间'],['night','黑白 · 夜间'],['neon','黑紫 · 霓虹'],['hacker','黑绿 · 黑客'],['custom','自定义色号']]],['deviceMode','客户端布局','select',[['auto','自动检测'],['pc','电脑'],['phone','手机竖屏'],['tablet','平板横屏']]],['mobileShortcuts','手机 / 平板启用电脑快捷键','checkbox']],editor:[['beatFormat','拍数显示','select',[['both','MC 数组 + 小数'],['tuple','MC 大拍数组'],['decimal','小数拍']]],['rulerSize','左侧数字字号 · px','number',7,30,1],['rulerColor','左侧数字颜色','color'],['rulerMode','左侧数字类型','select',[['bar','小节'],['beat','拍']]],['wheelDirection','滚轮浏览','select',[['natural','自然方向'],['legacy','旧版反向']]]],preview:[['playfieldOpacity','播放画面不透明度 · %','range',0,100,1],['comboPosition','Combo 位置','select',[['center','最中间'],['right','中右'],['left','中左'],['top','正上']]],['showFps','显示实测帧率','checkbox'],['targetFps','预览目标帧率','select',[[60,'60 FPS'],[120,'120 FPS']]],['preload','播放预加载','select',[['off','关闭'],['near','预览线前后各 10 秒'],['all','全曲']]],['classicShowHolds','经典谱使用秀谱六边形长条头尾','checkbox'],['innerApproachRing','内圈显示收缩提示圆环','checkbox'],['innerNoteOpacity','内圈音符相对不透明度 · %','range',0,100,1],['hitFx','打击特效不透明度 · %','range',0,100,1]]};
function open(){const p=clone(hooks.settings()),original=clone(p),e=hooks.esc;let pendingFile=null,pendingSound=null,soundJob=null,soundRevision=0;function input(key,label,type,choices,max,step,value=p[key]){return`<label class="field ${type==='checkbox'?'check-field':type==='range'?'range-setting':''}">${e(label)}${type==='select'?`<select data-pref="${key}">${choices.map(([v,name])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${e(name)}</option>`).join('')}</select>`:type==='checkbox'?`<input data-pref="${key}" type="checkbox" ${value?'checked':''}>`:`<input data-pref="${key}" type="${type}" value="${e(type==='color'?S.hex6(value):value)}" ${type==='color'?`data-original-color="${e(value)}"`:''} ${type==='range'||type==='number'?`min="${choices}" max="${max}" step="${type==='number'?'any':step}"`:''}>${type==='range'?`<output>${e(value)}</output>`:''}`}</label>`;}
hooks.open(hooks.header('⚙ 网页设置')+`<div class="modal-content web-settings"><p class="modal-copy">仅影响本站，自动记在此浏览器。选填数值留空会沿用已应用的值；只检查当前启用的选项。JSON 不包含舞立方账号、token、歌曲或谱面。</p><form id="webSettingsForm" novalidate><details class="web-setting-group"><summary>🎨 风格设置</summary><div class="settings-grid">${fields.style.map(f=>input(...f)).join('')}</div><h4>板块不透明度 · 默认 70%</h4><div class="settings-grid">${[['sidebar','左侧栏'],['topbar','顶部导航栏'],['editor','谱面编辑区'],['preview','实时预览']].map(([key,label])=>input('panelOpacity.'+key,label+' · %','range',0,100,1,p.panelOpacity[key])).join('')}</div><details class="settings-subgroup" id="customThemeColors"><summary>自定义主题 · 各区域色号</summary><div class="settings-grid color-grid">${Object.entries(p.customColors).map(([k,v])=>`<label class="field">${fieldNames[k]||k}<input type="color" data-theme-color="${k}" value="${S.hex6(v)}"><input type="text" data-theme-hex="${k}" value="${v}" aria-label="${fieldNames[k]||k}色号" pattern="#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})"></label>`).join('')}</div></details><h4>网站背景 · 页面最底层</h4><div class="settings-grid">${input('background.enabled','启用网站背景','checkbox',null,null,null,p.background.enabled)}${input('background.opacity','不透明度 · %','range',0,100,1,p.background.opacity)}${input('background.mode','展示方式','select',[['center','完全居中 · 原尺寸'],['static','静止 · 铺满'],['follow','指定倍率 · 跟随鼠标']],null,null,p.background.mode)}${input('background.zoom','放大倍率','number',.1,10,.05,p.background.zoom)}${input('background.type','外部 URL 类型','select',[['auto','自动判断'],['image','图片'],['video','视频'],['page','网页壁纸']],null,null,p.background.type)}<label class="field">导入本地图片 / 视频<input id="webBackgroundFile" type="file" accept="image/*,video/*"><small id="webBackgroundName">${e(backgroundRecord?.name||'未导入本地文件')}</small></label><label class="field wide-field">外部 URL<input id="webBackgroundURL" type="url" value="${e(p.background.url)}" placeholder="https://…"></label><label class="field">背景来源<select id="webBackgroundSource"><option value="url" ${p.background.source==='url'?'selected':''}>外部 URL</option><option value="local" ${p.background.source==='local'?'selected':''}>已导入本地文件</option></select></label></div><p class="field-hint">HTTPS 页面会将普通 HTTP 地址升级为 HTTPS。默认壁纸服务器暂不提供可用 HTTPS，本站使用随版本保存的壁纸副本；原 URL 保留。网页壁纸运行在隔离框架中。背景异常：${e($('webBackground')?.dataset.error||'无')}。</p></details><details class="web-setting-group"><summary>▥ 谱面编辑区设置</summary><div class="settings-grid">${fields.editor.map(f=>input(...f)).join('')}</div><details class="settings-subgroup"><summary>逐条节拍线与辅助线设置</summary><div class="line-style-head"><span>线条</span><span>颜色</span><span>粗细 px</span><span>不透明 %</span><span>线头</span><span>线型</span></div>${S.LINES.map(([key,label])=>{const s=p.lineStyles[key];return`<div class="line-style-row" data-line="${key}"><span>${label}</span><input type="color" data-line-prop="color" value="${S.hex6(s.color)}" data-original-color="${e(s.color)}" aria-label="${label}颜色"><input type="number" data-line-prop="width" min="0" max="30" step="any" value="${s.width}" aria-label="${label}粗细"><input type="number" data-line-prop="opacity" min="0" max="100" step="any" value="${s.opacity}" aria-label="${label}透明度"><select data-line-prop="cap" aria-label="${label}线头">${[['butt','平头'],['round','圆头'],['square','方头']].map(([v,n])=>`<option value="${v}" ${s.cap===v?'selected':''}>${n}</option>`).join('')}</select><select data-line-prop="pattern" aria-label="${label}线型">${[['solid','实线'],['dashed','虚线'],['dotted','点线']].map(([v,n])=>`<option value="${v}" ${s.pattern===v?'selected':''}>${n}</option>`).join('')}</select></div>`;}).join('')}</details><p class="field-hint">交点采用最简分拍归类，例如 1/4 的中点属于 1/2 线。当前节拍细分控制可见的线；粗细设为 0 可隐藏。</p></details><details class="web-setting-group"><summary>⬡ 预览区域与画面设置</summary><div class="settings-grid">${fields.preview.map(f=>input(...f)).join('')}</div><p class="field-hint">物量：单点 1，假键 0，长条 / 内圈长条 / 整根滑条均为 1 + floor(持续秒数 ÷ 0.2)，滑条再乘堆叠次数。计数与播放倍速、帧率无关。</p><h4>画面位置微调 · 参考画面 pixel</h4><p class="field-hint">以 700 × 808 为基准，数值随全屏 / 局部画面同比缩放。正值远离中心，负值靠近中心。位置在原判定 / 生成点基础上偏移；时间与判定时刻保持一致。长条特效相对音符位置。极端值可能令音符重叠。</p><div class="settings-grid">${[['outer','外圈消失点相对判定线'],['inner','内圈消失点相对判定线'],['spawn','生成点相对判定线'],['holdFx','长条特效相对音符']].map(([key,label])=>`<label class="field">${label}<input data-offset="${key}" type="number" step="any" value="${p.previewOffsets[key]}"></label>`).join('')}</div><p class="field-hint">目标帧率受屏幕与浏览器限制，当前约 ${hooks.refresh()||'检测中'} Hz。内圈单点按 10050—10056 逐帧播放，沿对应内框边线排列。秀谱外框随滑条旋转。</p><div class="cursor-setting"><b>网页外圈光标</b><span>${e(p.cursorOverride?p.cursorName||'账号光标':'内置 / 当前皮肤')}</span><button type="button" id="clearWebCursor">恢复当前皮肤光标</button><small>可在账号中心 → 道具与装扮 → 皮肤·光标选择“网页预览”。单张贴图只替换外圈单押单点，保持原比例。</small></div></details><details class="web-setting-group"><summary>♩ 节拍音与延迟校准</summary><div class="settings-grid">${input('beatSound.enabled','启用节拍音','checkbox',null,null,null,p.beatSound.enabled)}${input('beatSound.type','音效','select',[...(root.DCBeatSound?.TYPES||[['clear','清脆'],['electric','电波'],['dull','沉闷'],['moderate','适中']]),['custom','上传音效']],null,null,p.beatSound.type)}${input('beatSound.volume','节拍音音量 · %','range',0,100,1,p.beatSound.volume)}${input('beatSound.delay2Ms','二级延迟 · 浏览器 / 设备补偿 ms','number',-10000,10000,1,p.beatSound.delay2Ms)}</div><div id="customBeatSoundFields"><label class="field">上传音效 · 最长 10 秒 / 10 MB<input id="webBeatSoundFile" type="file" accept="audio/*,.wav,.ogg,.mp3,.m4a,.flac"><small id="webBeatSoundName">${e(soundRecord?.name||'未上传')}</small></label><div class="settings-grid">${input('beatSound.autoCalibrate','上传后自动分析起音并校准','checkbox',null,null,null,p.beatSound.autoCalibrate)}${input('beatSound.delay1Ms','一级延迟 · 音效文件起音 ms','number',0,10000,1,p.beatSound.delay1Ms)}</div><button type="button" id="analyzeBeatSound">分析并校准一级延迟</button></div><div class="modal-actions"><button id="auditionBeatSound" type="button">试听音效</button><output id="beatSoundDelayTotal" aria-live="polite"></output></div><p class="field-hint">总延迟 = 一级延迟 + 二级延迟。正值提前发声，负值延后发声；内置音效的一级延迟为 0。一级分析测量文件开头的静音，二级请听感调整；不会自动测量扬声器延迟。节拍音经过主音量输出。</p><p class="field-hint">预卷在 [-2,0,4]、[-2,1,4]、[-2,2,4]、[-2,3,4] 各响一次；随后按普通单点、内圈单点和所有长条 / 滑条头部的刻度线发声，同拍去重，假键不发声。暂停、跳转会取消待播音效。</p></details><details class="web-setting-group"><summary>⇄ 设置迁移</summary><p class="field-hint">配置会覆盖网页设置。勾选后可把本地背景、网页光标与上传音效一并写入 JSON，文件会增大；账号登录信息始终不会导出。</p><label class="check-line"><input id="includeWebMedia" type="checkbox"> 导出包含本地背景 / 网页光标 / 节拍音</label><div class="modal-actions"><button id="exportWebSettings" type="button">导出设置 JSON</button><label class="button-link">导入并应用 JSON<input id="importWebSettings" type="file" accept=".json,application/json" hidden></label></div></details><p id="webSettingsStatus" role="status"></p><div class="modal-actions"><button id="restoreWebDefaults" type="button">恢复网页默认设置…</button><button type="submit" class="primary">应用设置</button></div><div id="webResetConfirm" hidden><p class="modal-copy">确认恢复网页默认设置？歌曲、谱面、音乐和皮肤保留。</p><button id="confirmWebDefaults" type="button">确认恢复默认</button></div></form></div>`,true);
const form=$('webSettingsForm'),status=s=>{const el=$('webSettingsStatus');if(el&&form.isConnected)el.textContent=s;},close=()=>{if(form.isConnected&&$('webSettingsForm')===form)$('modal').close();};for(const el of form.querySelectorAll('[data-pref]')){if(el.type==='range')el.oninput=()=>el.nextElementSibling.textContent=el.value;if(el.dataset.pref==='targetFps')for(const option of el.options)option.disabled=+option.value>60&&(!hooks.refresh()||hooks.refresh()<+option.value*.9);if(el.dataset.pref==='preload')for(const option of el.options)option.disabled=option.value!=='off'&&(!hooks.refresh()||hooks.refresh()<100);}
for(const el of form.querySelectorAll('[data-theme-color]'))el.oninput=()=>form.querySelector(`[data-theme-hex="${el.dataset.themeColor}"]`).value=el.value;for(const el of form.querySelectorAll('[data-theme-hex]'))el.oninput=()=>{if(S.color(el.value))form.querySelector(`[data-theme-color="${el.dataset.themeHex}"]`).value=S.hex6(el.value);};
$('webBackgroundFile').onchange=event=>{pendingFile=event.target.files[0];if(pendingFile){$('webBackgroundName').textContent=pendingFile.name;$('webBackgroundSource').value='local';}};$('clearWebCursor').onclick=()=>{p.cursorOverride=false;p.cursorName='';status('应用设置后恢复当前皮肤光标');};
function colorValue(el){const original=el.dataset.originalColor;return original&&S.hex6(original).toLowerCase()===el.value.toLowerCase()?original:el.value;}
function invalid(el,message){el.setAttribute('aria-invalid','true');for(let node=el.parentElement;node&&node!==form;node=node.parentElement)if(node.tagName==='DETAILS')node.open=true;el.focus();throw Error(message);}
function numeric(el,fallback){if(el.validity?.badInput)invalid(el,'请填写有效数字');if(!el.value.trim())return fallback;const value=Number(el.value);if(!Number.isFinite(value))invalid(el,'请填写有效数字');if(el.min!==''&&value<Number(el.min)||el.max!==''&&value>Number(el.max))invalid(el,'数值范围为 '+el.min+'—'+el.max);return value;}
function collect(){form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));for(const el of form.querySelectorAll('[data-pref]')){const keys=el.dataset.pref.split('.'),target=keys.length===2?p[keys[0]]:p,key=keys.at(-1),fallback=keys.length===2?original[keys[0]][key]:original[key];if(el.disabled)continue;target[key]=el.type==='checkbox'?el.checked:el.type==='number'||el.type==='range'||key==='targetFps'?numeric(el,fallback):el.type==='color'?colorValue(el):el.value||fallback;}p.background.url=$('webBackgroundURL').value.trim();p.background.source=$('webBackgroundSource').value||original.background.source;for(const el of form.querySelectorAll('[data-theme-hex]')){const v=el.value.trim();if(S.color(v))p.customColors[el.dataset.themeHex]=v;else if(v&&p.theme==='custom')invalid(el,'自定义主题色号无效，请使用 #RGB、#RRGGBB 或 #RRGGBBAA');else p.customColors[el.dataset.themeHex]=original.customColors[el.dataset.themeHex];}for(const row of form.querySelectorAll('[data-line]'))for(const el of row.querySelectorAll('[data-line-prop]'))p.lineStyles[row.dataset.line][el.dataset.lineProp]=el.type==='number'?numeric(el,original.lineStyles[row.dataset.line][el.dataset.lineProp]):el.type==='color'?colorValue(el):el.value;for(const el of form.querySelectorAll('[data-offset]'))p.previewOffsets[el.dataset.offset]=numeric(el,original.previewOffsets[el.dataset.offset]);const bg=p.background;if(bg.enabled&&bg.opacity>0&&bg.source==='url'&&bg.url)try{S.effectiveURL(bg.url);}catch(err){invalid($('webBackgroundURL'),err.message);}return S.normalize(p);}
function updateDependencies(){const enabled=form.querySelector('[data-pref="background.enabled"]').checked,opacity=Number(form.querySelector('[data-pref="background.opacity"]').value),source=$('webBackgroundSource').value,active=enabled&&opacity>0;for(const key of ['background.mode','background.type','background.zoom']){const el=form.querySelector('[data-pref="'+key+'"]');el.disabled=!active||key==='background.type'&&source!=='url'||key==='background.zoom'&&form.querySelector('[data-pref="background.mode"]').value!=='follow';}$('webBackgroundURL').disabled=!active||source!=='url';$('webBackgroundFile').disabled=!active;const custom=form.querySelector('[data-pref="beatSound.type"]').value==='custom';$('customBeatSoundFields').hidden=!custom;for(const el of $('customBeatSoundFields').querySelectorAll('input,button'))el.disabled=!custom;updateSoundTotal();}
for(const el of [form.querySelector('[data-pref="background.enabled"]'),form.querySelector('[data-pref="background.opacity"]'),form.querySelector('[data-pref="background.mode"]'),form.querySelector('[data-pref="beatSound.type"]'),$('webBackgroundSource')]){el.addEventListener('input',updateDependencies);el.addEventListener('change',updateDependencies);}const fileChange=$('webBackgroundFile').onchange;$('webBackgroundFile').onchange=event=>{fileChange(event);updateDependencies();};updateDependencies();
function updateSoundTotal(){const type=form.querySelector('[data-pref="beatSound.type"]').value,a=type==='custom'?Number(form.querySelector('[data-pref="beatSound.delay1Ms"]').value)||0:0,b=Number(form.querySelector('[data-pref="beatSound.delay2Ms"]').value)||0;$('beatSoundDelayTotal').textContent='总延迟 '+ +(a+b).toFixed(3)+' ms';}
for(const el of form.querySelectorAll('[data-pref^="beatSound."]'))el.addEventListener('input',updateSoundTotal);
function ensureSoundReady(){if(soundJob)throw Error('音效正在分析，请稍候');}
async function soundFile(file){if(file.size>10*1024*1024)throw Error('节拍音文件不能超过 10 MB');const mime=file.type||(/\.wav$/i.test(file.name)?'audio/wav':/\.ogg$/i.test(file.name)?'audio/ogg':'audio/mpeg');if(!mime.startsWith('audio/'))throw Error('请选择音频文件');return{name:file.name.slice(0,200),mime,data:new Uint8Array(await file.arrayBuffer())};}
$('webBeatSoundFile').onchange=event=>{const file=event.target.files[0];event.target.value='';if(!file)return;const revision=++soundRevision;soundJob=(async()=>{if(!hooks.beatAudio)throw Error('此浏览器暂不支持音效解码');status('正在读取并分析音效…');const record=await soundFile(file);await hooks.beatAudio.decode(record);const auto=form.querySelector('[data-pref="beatSound.autoCalibrate"]').checked,ms=auto?await hooks.beatAudio.analyze(record):null;if(!form.isConnected||revision!==soundRevision)return;pendingSound=record;p.beatSound.customName=record.name;$('webBeatSoundName').textContent=record.name;if(ms!==null)form.querySelector('[data-pref="beatSound.delay1Ms"]').value=String(ms);updateSoundTotal();status(auto?'起音已校准为 '+ms+' ms，可试听并调整二级延迟':'音效已读取，请确认一级延迟；无前置静音可设为 0');})().catch(error=>status(error.message)).finally(()=>{if(revision===soundRevision)soundJob=null;});};
$('analyzeBeatSound').onclick=async()=>{try{ensureSoundReady();if(!hooks.beatAudio)throw Error('此浏览器暂不支持音效分析');soundJob=hooks.beatAudio.analyze(pendingSound||soundRecord);const ms=await soundJob;if(!form.isConnected)return;form.querySelector('[data-pref="beatSound.delay1Ms"]').value=String(ms);updateSoundTotal();status('起音已校准为 '+ms+' ms');}catch(error){status(error.message);}finally{soundJob=null;}};
$('auditionBeatSound').onclick=async()=>{try{ensureSoundReady();if(!hooks.beatAudio)throw Error('此浏览器暂不支持音效试听');await hooks.beatAudio.audition(collect().beatSound,pendingSound||soundRecord);status('试听完成；请播放谱面确认与节拍线对齐');}catch(error){status(error.message);}};
async function commit(value){ensureSoundReady();const local=value.background.enabled&&value.background.opacity>0&&value.background.source==='local',records=pendingFile&&local?{background:await fileRecord(pendingFile)}:{};if(pendingSound&&value.beatSound.type==='custom')records.beatSound=pendingSound;return commitPreferences(value,records);}

form.onsubmit=async event=>{event.preventDefault();try{const messages=await commit(collect());close();hooks.toast(['网页设置已保存',...messages].join('；'));}catch(err){status(err.message);}};
$('exportWebSettings').onclick=async()=>{try{ensureSoundReady();const value=collect(),output=S.pack(value),records={background:pendingFile&&value.background.enabled&&value.background.opacity>0&&value.background.source==='local'?await fileRecord(pendingFile):backgroundRecord,cursor:cursorRecord,beatSound:pendingSound||soundRecord};output.mediaRefs={};if(value.beatSound.type==='custom'&&records.beatSound)output.mediaRefs.beatSound=mediaRef(records.beatSound);if(value.background.source==='local'&&records.background)output.mediaRefs.background=mediaRef(records.background);if(value.cursorOverride&&records.cursor)output.mediaRefs.cursor=mediaRef(records.cursor);if($('includeWebMedia').checked){output.media={};for(const[key,record]of Object.entries(records))if(record){let binary='';for(let i=0;i<record.data.length;i+=32768)binary+=String.fromCharCode(...record.data.slice(i,i+32768));output.media[key]={name:record.name,mime:record.mime,base64:btoa(binary)};}}hooks.download(JSON.stringify(output,null,2),'DanceCube-web-settings.json','application/json');status('已导出网站设置');}catch(err){status(err.message);}};
$('importWebSettings').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;const raw=JSON.parse(await file.text()),value=S.unpack(raw),records=readMedia(raw.media||{}),refs=raw.mediaRefs||{};if(typeof refs!=='object'||Array.isArray(refs))throw Error('配置媒体校验信息无效');const messages=await commitPreferences(value,records,refs);pendingFile=null;close();hooks.toast(['已导入并应用网站设置',...messages].join('；'));}catch(err){status('导入失败：'+err.message);}finally{event.target.value='';}};
$('restoreWebDefaults').onclick=()=>$('webResetConfirm').hidden=false;$('confirmWebDefaults').onclick=async()=>{try{const messages=await commitPreferences(clone(root.DCProject.DEFAULT_SETTINGS),defaultRecords);close();hooks.toast(['网页默认设置已恢复',...messages].join('；'));}catch(err){status('恢复默认失败：'+err.message);}};}

